import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const AdminDashboard: React.FC = () => {
  const [products, setProducts] = useState([]);
  const [requests, setRequests] = useState([]);
  const [deadline, setDeadline] = useState(null);
  const [newProduct, setNewProduct] = useState({ name: '', type: '', max_quantity: 1 });
  const [editingProduct, setEditingProduct] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const token = localStorage.getItem('admin_token');

  useEffect(() => {
    if (!token) {
      navigate('/admin/login');
      return;
    }
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const headers = { Authorization: `Bearer ${token}` };
      
      const [productsRes, requestsRes, deadlineRes] = await Promise.all([
        axios.get('/api/products/public'),
        axios.get('/api/admin/requests', { headers }),
        axios.get('/api/settings/deadline')
      ]);
      
      setProducts(productsRes.data);
      setRequests(requestsRes.data);
      setDeadline(deadlineRes.data.edit_deadline);
    } catch (error) {
      if (error.response?.status === 401) {
        navigate('/admin/login');
      }
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddProduct = async (e) => {
    e.preventDefault();
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.post('/api/products', newProduct, { headers });
      setNewProduct({ name: '', type: '', max_quantity: 1 });
      setMessage('✅ محصول با موفقیت اضافه شد');
      fetchData();
    } catch (error) {
      setMessage('❌ خطا در افزودن محصول');
    }
  };

  const handleDeleteProduct = async (id) => {
    if (!window.confirm('آیا از حذف این محصول مطمئن هستید؟')) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`/api/products/${id}`, { headers });
      setMessage('✅ محصول با موفقیت حذف شد');
      fetchData();
    } catch (error) {
      setMessage('❌ خطا در حذف محصول');
    }
  };

  const handleToggleEdit = async (requestId, currentStatus) => {
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.put(`/api/admin/requests/${requestId}/toggle-edit?is_editable=${!currentStatus}`, {}, { headers });
      setMessage('✅ وضعیت ویرایش به‌روزرسانی شد');
      fetchData();
    } catch (error) {
      setMessage('❌ خطا در به‌روزرسانی وضعیت');
    }
  };

  const handleDeleteRequest = async (id) => {
    if (!window.confirm('آیا از حذف این محصول مطمئن هستید؟')) return;
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.delete(`/api/admin/requests/${id}`, { headers });
      setMessage('✅ درخواست با موفقیت حذف شد');
      fetchData();
    } catch (error) {
      setMessage('❌ خطا در حذف درخواست');
    }
  };

  const handleUpdateDeadline = async (e) => {
    e.preventDefault();
    try {
      const headers = { Authorization: `Bearer ${token}` };
      await axios.put('/api/settings/deadline', { edit_deadline: deadline }, { headers });
      setMessage('✅ تاریخ ویرایش با موفقیت به‌روزرسانی شد');
    } catch (error) {
      setMessage('❌ خطا در به‌روزرسانی تاریخ');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('admin_token');
    navigate('/admin/login');
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="max-w-7xl mx-auto">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold text-gray-800">پنل مدیریت</h1>
          <button
            onClick={handleLogout}
            className="bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-600"
          >
            خروج
          </button>
        </div>

        {message && (
          <div className={`p-3 rounded-md mb-4 ${message.includes('✅') ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
            {message}
          </div>
        )}

        {/* Products Management */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">مدیریت محصولات</h2>
          
          <form onSubmit={handleAddProduct} className="grid grid-cols-1 md:grid-cols-4 gap-3 mb-4">
            <input
              type="text"
              placeholder="نام محصول"
              required
              className="px-3 py-2 border border-gray-300 rounded-md"
              value={newProduct.name}
              onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
            />
            <input
              type="text"
              placeholder="نوع محصول"
              required
              className="px-3 py-2 border border-gray-300 rounded-md"
              value={newProduct.type}
              onChange={(e) => setNewProduct({...newProduct, type: e.target.value})}
            />
            <input
              type="number"
              placeholder="حداکثر تعداد"
              required
              min="1"
              className="px-3 py-2 border border-gray-300 rounded-md"
              value={newProduct.max_quantity}
              onChange={(e) => setNewProduct({...newProduct, max_quantity: parseInt(e.target.value) || 1})}
            />
            <button type="submit" className="bg-blue-600 text-white py-2 rounded-md hover:bg-blue-700">
              افزودن محصول
            </button>
          </form>

          <div className="overflow-x-auto">
            <table className="min-w-full bg-white border">
              <thead>
                <tr className="bg-gray-50">
                  <th className="px-4 py-2 border text-right">نام</th>
                  <th className="px-4 py-2 border text-right">نوع</th>
                  <th className="px-4 py-2 border text-right">حداکثر تعداد</th>
                  <th className="px-4 py-2 border text-right">عملیات</th>
                </tr>
              </thead>
              <tbody>
                {products.map((product) => (
                  <tr key={product.id}>
                    <td className="px-4 py-2 border">{product.name}</td>
                    <td className="px-4 py-2 border">{product.type}</td>
                    <td className="px-4 py-2 border">{product.max_quantity}</td>
                    <td className="px-4 py-2 border">
                      <button
                        onClick={() => handleDeleteProduct(product.id)}
                        className="bg-red-500 text-white px-3 py-1 rounded-md hover:bg-red-600 text-sm"
                      >
                        حذف
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Requests Management */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">مدیریت درخواست‌ها</h2>
          
          <div className="overflow-x-auto">
            <table className="min-w-full bg-white border">
              <thead>
                <tr className="bg-gray-50">
                  <th className="px-4 py-2 border text-right">کد پرسنلی</th>
                  <th className="px-4 py-2 border text-right">نام</th>
                  <th className="px-4 py-2 border text-right">وضعیت</th>
                  <th className="px-4 py-2 border text-right">تاریخ ثبت</th>
                  <th className="px-4 py-2 border text-right">قابل ویرایش</th>
                  <th className="px-4 py-2 border text-right">عملیات</th>
                </tr>
              </thead>
              <tbody>
                {requests.map((req) => (
                  <tr key={req.id}>
                    <td className="px-4 py-2 border">{req.employee_code}</td>
                    <td className="px-4 py-2 border">{req.full_name}</td>
                    <td className="px-4 py-2 border">{req.employment_status}</td>
                    <td className="px-4 py-2 border">{new Date(req.submitted_at).toLocaleDateString('fa-IR')}</td>
                    <td className="px-4 py-2 border">
                      {req.is_editable ? '✅ فعال' : '❌ غیرفعال'}
                    </td>
                    <td className="px-4 py-2 border">
                      <button
                        onClick={() => handleToggleEdit(req.id, req.is_editable)}
                        className={`px-3 py-1 rounded-md text-sm mr-1 ${
                          req.is_editable 
                            ? 'bg-yellow-500 text-white hover:bg-yellow-600' 
                            : 'bg-green-500 text-white hover:bg-green-600'
                        }`}
                      >
                        {req.is_editable ? 'غیرفعال' : 'فعال'}
                      </button>
                      <button
                        onClick={() => handleDeleteRequest(req.id)}
                        className="bg-red-500 text-white px-3 py-1 rounded-md hover:bg-red-600 text-sm"
                      >
                        حذف
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Deadline Settings */}
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">تنظیمات تاریخ ویرایش</h2>
          <form onSubmit={handleUpdateDeadline} className="flex items-end gap-4">
            <div className="flex-1">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                تاریخ و زمان آخرین فرصت ویرایش
              </label>
              <input
                type="datetime-local"
                className="w-full px-3 py-2 border border-gray-300 rounded-md"
                value={deadline || ''}
                onChange={(e) => setDeadline(e.target.value)}
              />
            </div>
            <button type="submit" className="bg-blue-600 text-white px-6 py-2 rounded-md hover:bg-blue-700">
              ذخیره
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
